args.sql:
SELECT 
    FLOOR((CURRENT_DATE - '1985-01-07'::date) / 365.25) as age_floor,
    EXTRACT(YEAR FROM AGE(CURRENT_DATE, TIMESTAMP '1985-01-07')) as age_extract;
